  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "KYP-2047, the query compound, penetrated the brain extracellular fluid in vivo after a single intraperitoneal dose, directly demonstrating meaningful BBB access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A related proline/piperidine amide (AD-8007) reached significantly higher brain levels than a comparator in mice, supporting CNS penetration for this peptidomimetic class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "A benzylpiperidine benzamide showed good brain uptake in mice, supporting that similar lipophilic amides can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "A pyrrolidine-containing PET tracer showed high brain uptake in rhesus monkeys (striatal SUV 4.45), supporting CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "The related CNS protease inhibitor GI254023X reached 2.2 µM in mouse pons after IP dosing, demonstrating meaningful brain penetration for similar inhibitors.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is KYP-2047, a prolyl oligopeptidase inhibitor with direct in vivo evidence of brain extracellular fluid penetration after systemic dosing. Multiple structurally related CNS-penetrant peptidomimetics and PET tracers further support meaningful BBB access, so the prediction is pass.",
  "evidence_gaps": [
    "No quantitative Kp,uu or CSF/plasma AUC for the query; C11 provides qualitative but direct brain ECF penetration evidence.",
    "Penicillin G records are contradictory but reflect an anionic beta-lactam class with different ionization/transport properties and are outweighed by direct KYP-2047 evidence.",
    "Most supporting analogues are not exact structural matches, though the query itself is named in C11."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

